21360	    /// Applies one final player-resource edit without replacements, quantity
21361	    /// evaluation, or an implicit player selection.
21362	    pub fn apply_resolved_player_edit(
21363	        &mut self,
21364	        command: &ResolvedPlayerEditCommand,
21365	    ) -> Result<(), ResolvedPlayerEditReplayInvariantError> {
21366	        let player = self
21367	            .players
21368	            .iter_mut()
21369	            .find(|candidate| candidate.id == command.player)
21370	            .ok_or(ResolvedPlayerEditReplayInvariantError::UnknownPlayer(
21371	                command.player,
21372	            ))?;
21373	
21374	        match &command.edit {
21375	            ResolvedPlayerEdit::Life { delta } => {
21376	                let amount = nonzero_delta_magnitude(*delta)?;
21377	                let life = player
21378	                    .life
21379	                    .checked_add(*delta)
21380	                    .ok_or(ResolvedPlayerEditReplayInvariantError::ResourceOverflow)?;
21381	                if *delta > 0 {
21382	                    let gained = player
21383	                        .life_gained_this_turn
21384	                        .checked_add(amount)
21385	                        .ok_or(ResolvedPlayerEditReplayInvariantError::ResourceOverflow)?;
21386	                    player.life = life;
21387	                    player.life_gained_this_turn = gained;
21388	                } else {
21389	                    let lost = player
21390	                        .life_lost_this_turn
21391	                        .checked_add(amount)
21392	                        .ok_or(ResolvedPlayerEditReplayInvariantError::ResourceOverflow)?;
21393	                    player.life = life;
21394	                    player.life_lost_this_turn = lost;
21395	                }
21396	            }
21397	            ResolvedPlayerEdit::Energy { delta } => {
21398	                player.energy = apply_u32_delta(player.energy, *delta)?;
21399	            }
21400	            ResolvedPlayerEdit::Counter { kind, delta } => {
21401	                let count = apply_u32_delta(player.player_counter(kind), *delta)?;
21402	                match kind {
21403	                    PlayerCounterKind::Poison => player.poison_counters = count,
21404	                    _ if count == 0 => {
21405	                        player.player_counters.remove(kind);
21406	                    }
21407	                    _ => {
21408	                        player.player_counters.insert(*kind, count);
21409	                    }
21410	                }
21411	            }
21412	            ResolvedPlayerEdit::Speed { old, new } => {
21413	                if player.speed != *old {
21414	                    return Err(
21415	                        ResolvedPlayerEditReplayInvariantError::SpeedPreconditionMismatch {
21416	                            expected: *old,
21417	                            found: player.speed,
21418	                        },
21419	                    );
21420	                }
21421	                if old == new {
21422	                    return Err(ResolvedPlayerEditReplayInvariantError::ZeroDelta);
21423	                }
21424	                player.speed = *new;
21425	            }
21426	        }
21427	        Ok(())
21428	    }
